import com.huawei.i2000.dvaiagentservice.cluster.query.QueryPhenomenonPair;
import com.huawei.i2000.dvaiagentservice.model.QueryParam;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * 功能描述
 *
 * @author x00660237
 * @since 2025/4/29
 */
@Service
public class IncidentCaseManager {

    public static final OssLog LOGGER = OssLogFactory.getLogger(IncidentCaseManager.class);

    @Autowired
    IncidentManage incidentManage;

    public static final String KNOWLEDGE_INDEX_DV = "common_klg_index_dv";

    public static final String KNOWLEDGE_INDEX_CBS = "cbs_case_knowledge";

    private static final ObjectMapper OBJECT_MAPPER;

    static {
        OBJECT_MAPPER = new ObjectMapper();
        OBJECT_MAPPER.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
    }

    public String generateQueryFromAnalysisPaths(Object analysisPathsObject)
        throws ServiceException {
        if (analysisPathsObject == null) {
            return null;
        }

        List<AnalysisPathEntry> analysisPathEntries;
        try {
            if (analysisPathsObject instanceof String) {
                analysisPathEntries = OBJECT_MAPPER.readValue((String)analysisPathsObject,
                    new TypeReference<List<AnalysisPathEntry>>() {
                    });
            } else if (analysisPathsObject instanceof List) {
                analysisPathEntries = OBJECT_MAPPER.convertValue(analysisPathsObject,
                    new TypeReference<List<AnalysisPathEntry>>() {
                    });
            } else {
                throw new ServiceException(
                    "Unsupported type for analysisPaths: " + analysisPathsObject.getClass().getName());
            }
        } catch (JsonProcessingException | IllegalArgumentException e) { // IllegalArgumentException for convertValue
            throw new ServiceException("Failed to parse or convert analysisPaths", e);
        }

        if (analysisPathEntries == null || analysisPathEntries.isEmpty()) {
            return null;
        }

        List<List<Node>> completePathList = analysisPathEntries.stream()
            .map(AnalysisPathEntry::getPath)
            .filter(Objects::nonNull)
            .collect(Collectors.toList());

        if (completePathList.isEmpty()) {
            return null;
        }

        FaultPathGenerator pathGenerator = new FaultPathGenerator(completePathList);
        List<List<List<Node>>> filteredGroupedPaths = pathGenerator.getFilteredTopPath();

        if (filteredGroupedPaths.isEmpty()) {
            return null;
        }

        FaultQueryGenerator queryGenerator = new FaultQueryGenerator(filteredGroupedPaths);
        List<QueryPhenomenonPair> queryPairs = queryGenerator.getQuery();

        return queryPairs.isEmpty() ? null : queryPairs.get(0).getQuery();
    }

    public QueryParam getIncidentCaseQuery(Incident incident)
        throws ServiceException {
        QueryParam queryParam = new QueryParam();
        String baseQuery = "";

        baseQuery = getBaseQuery(incident, baseQuery);

        if (EventType.ALARM.toString().equals(incident.getCategory())) {
            queryParam.setQuery(baseQuery);
            return queryParam;
        }

        // Generate query from analysis paths
        String pathQuery = generateQueryFromAnalysisPaths(incident.getAnalysisPaths());

        // TODO If pathQuery is null, use faultPhenomenon as fallback

        StringBuilder finalQueryBuilder = new StringBuilder();
        boolean baseQueryExists = !baseQuery.isEmpty();
        boolean pathQueryExists = pathQuery != null && !pathQuery.isEmpty();

        if (baseQueryExists) {
            finalQueryBuilder.append(baseQuery);
        }

        if (pathQueryExists) {
            if (baseQueryExists) {
                finalQueryBuilder.append(" "); // Separator
                finalQueryBuilder.append("Related Analysis: "); // Example separator phrase
            }
            finalQueryBuilder.append(pathQuery);
        }

        String finalQuery = finalQueryBuilder.toString();

        if (finalQuery.isEmpty()) {
            return queryParam;
        }

        queryParam.setQuery(finalQuery);
        queryParam.setIndexName(KNOWLEDGE_INDEX_CBS);
        return queryParam;
    }

    public String getBaseQuery(Incident incident, String baseQuery) {
        if (incident.getCategory() != null) {
            if (EventType.KPI.toString().equals(incident.getCategory())) {
                Event event = incident.getEvents()
                    .stream()
                    .filter(e -> EventType.KPI.equals(e.getType()))
                    .findFirst()
                    .orElse(null);
                if (event != null) {
                    baseQuery = ResourceUtil.getMessage("knowledge.query.kpi")
                        .replace("{meas_unit}", event.getEventId() != null ? event.getEventId() : "")
                        .replace("{kpi_name}", event.getName() != null ? event.getName() : "");
                }
            } else if (EventType.ALARM.toString().equals(incident.getCategory())) {
                Event event = incident.getEvents()
                    .stream()
                    .filter(e -> EventType.ALARM.equals(e.getType()))
                    .findFirst()
                    .orElse(null);
                if (event != null) {
                    baseQuery = ResourceUtil.getMessage("knowledge.query.alarm")
                        .replace("{alarm_id}", event.getEventId() != null ? event.getEventId() : "")
                        .replace("{alarm_name}", event.getName() != null ? event.getName() : "");
                }
            }
        }
        return baseQuery;
    }

    public List<IncidentCase> buildIncidentCases(KnowledgeRecommendsRsp knowledgeRecommendsRsp, Incident incident)
        throws ServiceException {
        Comparator<KnowledgeRsp> rankComparator = Comparator.comparingDouble(KnowledgeRsp::getRerankScore).reversed();
        Set<String> distinctKnowledgeSet = new HashSet<>();
        List<IncidentCase> collect = knowledgeRecommendsRsp.getRecommends()
            .stream()
            .sorted(rankComparator)
            .filter(knowledgeRsp -> distinctKnowledgeSet.add(KnowledgeQuery.extractKnowledgeData(knowledgeRsp)))
            .map(knowledgeRsp -> new IncidentCase(incident.getCsn(),
                incident.getEvents().stream().findFirst().map(Event::getType).map(EventType::toString).orElse(""),
                incident.getEvents().stream().findFirst().map(Event::getEventId).orElse(""),
                KnowledgeQuery.extractKnowledgeData(knowledgeRsp), knowledgeRsp.getLabel()))
            .collect(Collectors.toList());

        return collect;
    }
}
