/**
 * KnowledgeSearchServiceDelegateImpl
 *
 * @author w00430116
 * @since 2025/2/19
 */
@Component
public class KnowledgeSearchServiceDelegateImpl implements KnowledgeSearchServiceDelegate {
    private static final OssLog LOGGER = OssLogFactory.getLogger(KnowledgeSearchServiceDelegateImpl.class);

    public static final String RETRIEVER_KLG_URL = "/rest/naie/rag/v1/retriever";

    public static final BigDecimal SIMILARITY_THRESHOLD = new BigDecimal("0.3");

    /**
     * 正则匹配非法词模板
     */
    public static final Pattern PATTERN = Pattern.compile(
            "(?<!\\w)(agent|atlas|mindspore|gpu|llm|rag|cann't)(?!\\w)",
            Pattern.CASE_INSENSITIVE);

    /**
     * 创建非法词替换映射
     */
    static final Map<String, String> REPLACEMENT_MAP;

    static {
        REPLACEMENT_MAP = new HashMap<>();
        REPLACEMENT_MAP.put("atlas", "Taishan200");
        REPLACEMENT_MAP.put("mindspore", "Intelligent Platform-MS");
        REPLACEMENT_MAP.put("gpu", "SPU");
        REPLACEMENT_MAP.put("llm", "Large Language Model");
        REPLACEMENT_MAP.put("rag", "Retrieval-augmented Generation");
        REPLACEMENT_MAP.put("cann't", "cannot");
    }

    private KnowledgeRecommendsRsp getKnowledgeRecommendsRsp(HttpContext context, QueryParam queryParam)
            throws ServiceException {
        RetrieverReq retrieverReq = RetrieverReqBuilder.getRetrieverReq(queryParam);
        String param = JSON.toJSONString(retrieverReq);
        RestfulParametes restfulParametes = new RestfulParametes();
        restfulParametes.setRawData(param);
        RestfulResponse knowledgeRsp = RestUtil.sendRestRequest(context.getHttpServletRequest(),
                RestConstant.RESTFUL_METHOD_POST, RETRIEVER_KLG_URL, restfulParametes, null);
        if (knowledgeRsp == null || knowledgeRsp.getStatus() != RestConstant.STATUS_OK) {
            LOGGER.error("[knowledgeSearch] query knowledge error");
            throw new ServiceException("[knowledgeSearch] query knowledge error");
        }

        return JSON.parseObject(knowledgeRsp.getResponseContent(), KnowledgeRecommendsRsp.class);
    }


    /**
     * 匹配并替换内容中的非法词
     *
     * @param text 需要处理的文本
     * @return 非法词被替换后的文本
     */
    private String replaceInvalidWords(String text) {
        Matcher matcher = PATTERN.matcher(text);
        StringBuffer sb = new StringBuffer();
        // 遍历匹配结果并替换
        while (matcher.find()) {
            String matched = matcher.group(1);
            String replacement;
            if (matched.equalsIgnoreCase("agent")) {
                replacement = matched + "_";
            } else {
                replacement = REPLACEMENT_MAP.getOrDefault(matched.toLowerCase(Locale.ROOT), matched);
            }
            matcher.appendReplacement(sb, replacement);
        }
        matcher.appendTail(sb);
        return sb.toString();
    }

    @Override
    public KnowledgeResult knowledgeSearch(HttpContext context, QueryParam queryParam)
            throws ServiceException {
        KnowledgeRecommendsRsp knowledgeRecommendsRsp = getKnowledgeRecommendsRsp(context, queryParam);
        List<KnowledgeRsp> recommends = knowledgeRecommendsRsp.getRecommends();
        KnowledgeResult knowledge = new KnowledgeResult();
        LOGGER.info("[knowledgeSearch] recommends size is {}", recommends.size());
        if (CollectionUtils.isEmpty(recommends)) {
            return knowledge;
        }
        List<String> knowledgeLabelList = new ArrayList<>();
        Set<String> knowledgeSet = new LinkedHashSet<>();
        Set<String> sourceSet = new LinkedHashSet<>();
        for (KnowledgeRsp recommend : recommends) {
            if (SIMILARITY_THRESHOLD.compareTo(BigDecimal.valueOf(recommend.getVsScore())) < 0) {
                String knowledgeContent = KnowledgeQuery.extractKnowledgeData(recommend);
                // 替换source内容里的非法词
                String source = replaceInvalidWords(recommend.getSource());
                knowledgeSet.add(transformSource(knowledgeContent));
                sourceSet.add(source);
                knowledgeLabelList.add(
                        CollectionUtils.isEmpty(recommend.getLabel()) ? "" : recommend.getLabel().getFirst());
            }
        }
        // 知识去重
        LOGGER.info("[knowledgeSearch] Knowledge size is {}, source size is {}, ",
                knowledgeSet.size(), sourceSet.size());
        knowledge.getKnowledgeLabel().addAll(knowledgeLabelList);
        knowledge.getKnowledgeResult().addAll(knowledgeSet);
        knowledge.getSourceResult().addAll(sourceSet);
        knowledge.setToken(knowledge.getSourceResult().stream().mapToInt(String::length).sum());
        return knowledge;
    }

    public String transformSource(String knowledge) {
        String replaceSource = ResourceUtil.getMessage(IncidentConstant.USER_ARCHIVE);
        String result = knowledge.replace(LLM_GENERATE, replaceSource)
                .replace(USER_EDIT, replaceSource);
        return result;
    }
}
