            mapper.updateStatusWithUndeployed(reportTemplatePO);
        } catch (Exception e) {
            LOGGER.error("updateStatusWithUndeployed failed. {}", e.getMessage());
            throwServiceException(LOGGER, "update report template status with undeployed");
        }
    }
}
